{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A membership for calibrated listening</title>
  <meta name="description" content="Membership-led sound sessions and private work in {{CITY}}, {{STATE}}. Gentle, moving, or immersive sound practices tuned to everyday rhythms.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="page--lux">
  <header class="site-header">
    <div class="brand">
      <svg class="logo" width="48" height="48" viewBox="0 0 48 48" aria-hidden="true"><use href="#logo-shape"/></svg>
      <div>
        <h1 class="business">{{BUSINESS_NAME}}</h1>
        <p class="tag">{{TAGLINE}}</p>
      </div>
    </div>
    <nav class="main-nav">
      <a href="index.html">Gatherings</a>
      <a href="events.html">Calendar</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Memberships</a>
      <a href="about.html">About</a>
      <a href="faq.html">Q&amp;A</a>
      <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      <a href="contact.html" class="muted">Contact</a>
    </nav>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" id="hero">
      <svg class="pattern" aria-hidden="true"><use href="assets/img/pattern.svg#p"/></svg>
      <div class="hero-inner">
        <h2>Soundings tuned to the life you bring</h2>
        <p>Join a membership that offers tiered access to group sound sessions, member-only drop-ins, and private alignment work in {{CITY}}, {{STATE}}.</p>
        <div class="hero-cta">
          <a class="btn primary" href="book.html">Reserve a place</a>
          <a class="btn ghost" href="events.html">See next gatherings</a>
        </div>
        <p class="contact-line">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>

    <!-- Diagnostic (sound preference mixer) -->
    <section class="diagnostic" id="diagnostic">
      <h3>Find your listening intensity</h3>
      <p>Select a sound preference to see recommended membership tracks and session types.</p>
      <div class="mixer" role="radiogroup" aria-label="Sound intensity">
        <label class="mixer-option"><input type="radio" name="intensity" value="gentle"> Gentle</label>
        <label class="mixer-option"><input type="radio" name="intensity" value="medium" checked> Medium</label>
        <label class="mixer-option"><input type="radio" name="intensity" value="intense"> Intense</label>
      </div>
      <div id="recommendations" class="recs">
        <!-- JS will fill recommendations here -->
      </div>
    </section>

    <!-- Plan (membership framing) -->
    <section class="plan" id="plan">
      <h3>Memberships arranged as listening tracks</h3>
      <p>Choose a rhythm that fits your weeks. Memberships are billed monthly; cancel at any time.</p>
      <div class="tiers" id="tiers">
        <article class="tier" data-tier="ripple">
          <h4>Ripple — community access</h4>
          <p class="price">$24/mo</p>
          <ul>
            <li>Weekly group sessions</li>
            <li>Two member drop-in passes</li>
          </ul>
          <a class="btn" href="pricing.html#ripple">Join Ripple</a>
        </article>
        <article class="tier featured" data-tier="current">
          <h4>Current — steady practice</h4>
          <p class="price">$48/mo</p>
          <ul>
            <li>All Ripple benefits</li>
            <li>Monthly private check-in</li>
            <li>Priority booking</li>
          </ul>
          <a class="btn primary" href="pricing.html#current">Start Current</a>
        </article>
        <article class="tier" data-tier="deep">
          <h4>Deep — focused support</h4>
          <p class="price">$95/mo</p>
          <ul>
            <li>Weekly private sessions (limited)</li>
            <li>Unlimited group access</li>
            <li>Custom practice plan</li>
          </ul>
          <a class="btn" href="pricing.html#deep">Apply for Deep</a>
        </article>
      </div>
      <p class="pricing-note">Memberships include a short intake to ensure suitability. Contraindications apply — see the detailed notice below.</p>
    </section>

    <!-- Micro habits -->
    <section class="micro-habits" id="micro_habits">
      <h3>Daily micro-listens</h3>
      <p>Practical short practices you can use anywhere. Pick one and try it for a week.</p>
      <ul class="habits">
        <li><strong>Minute Return:</strong> One breath, one resonant tone, three counts rest.</li>
        <li><strong>Edge Check:</strong> Notice where tension sits and let sound move the edge.</li>
        <li><strong>Soft Sweep:</strong> Turn attention slowly from toes to crown with a low hum.</li>
      </ul>
      <a class="btn ghost" href="book.html">Try a guided micro-listen</a>
    </section>

    <!-- Pricing summary -->
    <section class="pricing" id="pricing">
      <h3>Flexible billing that meets regular life</h3>
      <p>Monthly membership is the simplest path; seasonal intensive passes are available on the schedule page.</p>
      <div class="pricing-capsules">
        <div class="cap">
          <h4>Drop-in</h4>
          <p class="cap-price">$20</p>
          <p>Single visit for first-time and one-off guests.</p>
        </div>
        <div class="cap">
          <h4>Membership</h4>
          <p class="cap-price">From $24/mo</p>
          <p>Recurring membership for steady practice.</p>
        </div>
        <div class="cap">
          <h4>Private</h4>
          <p class="cap-price">From $120</p>
          <p>One-on-one sessions for tailored work and contraindication-adapted plans.</p>
        </div>
      </div>
    </section>

    <!-- Proof Gallery: rotating testimonials + credibility badges -->
    <section class="proof" id="proof">
      <h3>Proof in practice</h3>
      <div class="proof-grid">
        <div class="testimonials" aria-live="polite">
          <blockquote class="quote">“A precise pause I keep returning to.”<cite>— L.</cite></blockquote>
          <blockquote class="quote">“A ritual that fits into busy weeks and changes how I rest.”<cite>— M.</cite></blockquote>
          <blockquote class="quote">“The private session unlocked a steady breath I hadn’t had in years.”<cite>— S.</cite></blockquote>
        </div>
        <aside class="badges" aria-hidden="false">
          <div class="badge" data-tip="Held to trauma-informed practice guidelines">Trauma-informed</div>
          <div class="badge" data-tip="Experienced facilitators with clinical affiliations">Clinician-affiliated</div>
          <div class="badge" data-tip="Local health &amp; safety vetted space">Verified studio</div>
        </aside>
      </div>
      <div class="proof-cta">
        <a class="btn" href="about.html">Meet our team</a>
        <a class="btn primary" href="book.html">Book a session</a>
      </div>
    </section>

    <!-- Events preview / next-event module -->
    <section class="events" id="events">
      <h3>Next gatherings</h3>
      <div class="next-event" id="nextEvent">
        <!-- JS fills next event -->
      </div>
      <div class="calendar-list" id="calendarList">
        <!-- JS generates calendar list; link to events.html for full calendar -->
      </div>
      <p class="small">Full schedule and seasonal intensives on the <a href="events.html">Calendar</a> page.</p>
    </section>

    <!-- Call to action -->
    <section class="final-cta" id="cta">
      <h3>Ready to tune your week?</h3>
      <p>Membership offers the clearest route to consistent listening. Pick a track and start small.</p>
      <div class="cta-row">
        <a class="btn primary large" href="pricing.html">View Memberships</a>
        <a class="btn ghost large" href="book.html">Book a trial</a>
      </div>
    </section>

    <!-- Contraindications disclaimer -->
    <section class="disclaimer" id="disclaimer">
      <h4>Important safety and contraindications</h4>
      <p>Sound sessions are supportive for many people but are not suitable for everyone. Please consult a clinician before attending if you have a history of seizure, epilepsy, uncontrolled cardiovascular conditions, recent surgery, extreme sound sensitivity, severe psychiatric conditions, or pregnancy concerns. Private sessions include an intake to identify adaptations. If in doubt, contact us at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </section>
  </main>

  <footer class="site-footer">
    <div class="footer-grid">
      <div>
        <p>&copy; <span id="year"></span> {{BUSINESS_NAME}}</p>
        <p class="muted">{{TAGLINE}}</p>
      </div>
      <div>
        <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav class="footer-nav">
        <a href="privacy.html">Privacy</a>
        <a href="terms.html">Terms</a>
        <a href="contact.html">Contact</a>
      </nav>
    </div>
  </footer>

  <!-- Accessible inline SVG symbols -->
  <svg style="display:none;" aria-hidden="true">
    <symbol id="logo-shape" viewBox="0 0 48 48">
      <circle cx="24" cy="24" r="10" fill="none" stroke="#222" stroke-width="2"/>
      <path d="M8 36c8-6 32-6 32 0" fill="none" stroke="#222" stroke-width="1.5" stroke-linecap="round"/>
    </symbol>
  </svg>
</body>
</html>"} 
