{"path":"assets/css/styles.css","content":"/* Core styles for sound_bath template */
:root{
  --bg:#fbfbfd; --muted:#70707a; --accent:#4766ff; --accent-2:#3db39e; --text:#111318; --card:#ffffff; --radius:12px;
  --maxw:1100px; font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:linear-gradient(180deg,var(--bg),#f6f8fa);color:var(--text);line-height:1.45}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:transparent;max-width:var(--maxw);margin:18px auto}
.brand{display:flex;gap:12px;align-items:center}
.brand .logo{border-radius:8px;background:#fff;padding:6px}
.business{margin:0;font-size:16px}
.tag{margin:0;color:var(--muted);font-size:13px}
.main-nav a{margin-left:14px;color:var(--muted);text-decoration:none}
.main-nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;text-decoration:none}
.main-nav .muted{opacity:0.8}

.hero{position:relative;overflow:hidden;border-radius:16px;margin:18px auto;max-width:var(--maxw);padding:48px;background:linear-gradient(135deg,#fff,#f4f6fb);box-shadow:0 6px 30px rgba(17,19,24,0.05)}
.hero .pattern{position:absolute;right:12px;top:12px;width:240px;height:240px;opacity:0.14}
.hero-inner{max-width:720px}
.hero h2{margin:0 0 8px;font-size:26px}
.hero p{margin:0 0 18px;color:var(--muted)}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;background:transparent;border:1px solid #e3e6ee;color:var(--text)}
.btn.primary{background:var(--accent);color:#fff;border:0}
.btn.ghost{background:transparent;border:1px solid rgba(17,19,24,0.06)}
.btn.large{padding:14px 20px}
.hero-cta{margin:18px 0}
.contact-line{color:var(--muted);font-size:13px}

section{padding:28px 22px;margin:18px auto;max-width:var(--maxw);background:transparent}
section h3{margin-top:6px}
.diagnostic{background:linear-gradient(180deg,#fff,#fbfdff);border-radius:12px;box-shadow:0 4px 18px rgba(12,14,20,0.04)}
.mixer{display:flex;gap:10px;margin:12px 0}
.mixer-option{background:#fff;padding:8px 12px;border-radius:8px;border:1px solid #e7ecf8;color:var(--muted)}
.recs{margin-top:12px;padding:12px;background:var(--card);border-radius:10px}

.plan .tiers{display:flex;gap:14px;margin-top:12px}
.tier{flex:1;background:var(--card);padding:14px;border-radius:12px;border:1px solid #f0f4fb}
.tier.featured{box-shadow:0 12px 30px rgba(71,102,255,0.08);transform:translateY(-6px)}
.tier .price{font-weight:700;color:var(--accent)}
.pricing-capsules{display:flex;gap:12px}
.cap{background:#fff;padding:12px;border-radius:10px;flex:1;border:1px solid #f1f5fb}

.micro-habits .habits{list-style:none;padding:0;margin:8px 0}
.micro-habits li{background:#fff;padding:10px;border-radius:8px;margin-bottom:8px;border:1px solid #f3f7fb}

.proof-grid{display:flex;gap:18px;align-items:flex-start}
.testimonials{flex:2;background:linear-gradient(180deg,#fff,#fbfbff);padding:16px;border-radius:10px;min-height:120px}
.quote{margin:0 0 12px;font-style:italic}
.quote cite{display:block;margin-top:8px;font-style:normal;color:var(--muted);font-size:13px}
.badges{display:flex;flex-direction:column;gap:8px;align-items:flex-start}
.badge{background:#fff;padding:8px 12px;border-radius:8px;border:1px solid #eef3fb;cursor:default}
.badge[data-show-tip]{position:relative}
.badge[data-show-tip]::after{content:attr(data-show-tip);position:absolute;left:110%;top:50%;transform:translateY(-50%);white-space:nowrap;background:#0b1220;color:#fff;padding:6px 8px;border-radius:6px;font-size:12px;box-shadow:0 8px 20px rgba(2,6,22,0.12);opacity:0;pointer-events:none;transition:opacity .18s}
.badge[data-show-tip="true"]::after{opacity:1}

.events .next-event{background:#fff;padding:14px;border-radius:10px;border:1px solid #eef3fb}
.calendar-list{margin-top:12px}
.calendar-item{background:#fff;padding:10px;border-radius:8px;margin-bottom:8px;border:1px solid #f1f5fb}
.calendar-item.next{border-color:var(--accent);box-shadow:0 8px 20px rgba(71,102,255,0.06)}

.final-cta{background:linear-gradient(90deg,#fff,#f9fbff);padding:20px;border-radius:12px;text-align:center}
.disclaimer{background:#fff7f0;padding:12px;border-radius:8px;border:1px solid #fff0e6;color:#5f3a22}

.site-footer{max-width:var(--maxw);margin:22px auto;padding:18px;color:var(--muted)}
.footer-grid{display:flex;justify-content:space-between;align-items:center}

@media(max-width:860px){.plan .tiers{flex-direction:column}.proof-grid{flex-direction:column}.main-nav{display:none}.site-header{padding:12px}}
"} 
{"path":"assets/js/main.js","content":"// Main interactivity for sound_bath template
document.addEventListener('DOMContentLoaded',function(){
  // Year
  document.getElementById('year').textContent = new Date().getFullYear();

  // Recommendations data keyed by intensity
  const recData = {
    gentle: {
      title: 'Gentle track — low resonance',
      bullets: ['Soft-chime introductions','Low-pitch sustained bowls','Short guided breath returns (10–12 minutes)'],
      suggest: 'Ripple or Current memberships fit most gentle listeners.'
    },
    medium: {
      title: 'Medium track — steady resonance',
      bullets: ['Layered bowls and chimes','Movement-informed sonics','20–40 minute guided sessions'],
      suggest: 'Current is designed for steady practice; try a month.'
    },
    intense: {
      title: 'Immersive track — deeper spectrum',
      bullets: ['Extended low-range vibrations','Intentional silence windows','Integrated private alignment options'],
      suggest: 'Deep membership or private series recommended; intake required.'
    }
  };

  // Populate initial recs
  const recContainer = document.getElementById('recommendations');
  function renderRecs(key){
    const d = recData[key];
    recContainer.innerHTML = '';
    const h = document.createElement('h4'); h.textContent = d.title;
    const ul = document.createElement('ul');
    d.bullets.forEach(b=>{const li=document.createElement('li');li.textContent=b;ul.appendChild(li)});
    const p = document.createElement('p'); p.className='muted small'; p.textContent = d.suggest;
    recContainer.appendChild(h); recContainer.appendChild(ul); recContainer.appendChild(p);
  }

  // Hook up radio buttons
  document.querySelectorAll('input[name="intensity"]').forEach(radio=>{
    radio.addEventListener('change',e=>{renderRecs(e.target.value)});
  });
  // initial
  renderRecs(document.querySelector('input[name="intensity"]:checked').value);

  // Testimonials rotation
  const quotes = Array.from(document.querySelectorAll('.testimonials .quote'));
  let current = 0;
  function showQuote(i){
    quotes.forEach((q,idx)=>{q.style.display = idx===i ? 'block':'none';});
  }
  if(quotes.length){
    showQuote(0);
    setInterval(()=>{ current = (current+1)%quotes.length; showQuote(current); },4500);
  }

  // Badges tooltips / hover behavior
  const badges = document.querySelectorAll('.badge');
  badges.forEach(badge=>{
    const tip = badge.getAttribute('data-tip');
    if(!tip) return;
    // store tip text for accessibility
    badge.setAttribute('aria-label', tip);
    // on mouseenter, flip data-show-tip
    badge.addEventListener('mouseenter', ()=> badge.setAttribute('data-show-tip','true'));
    badge.addEventListener('mouseleave', ()=> badge.setAttribute('data-show-tip','false'));
    // on focus for keyboard
    badge.addEventListener('focus', ()=> badge.setAttribute('data-show-tip','true'));
    badge.addEventListener('blur', ()=> badge.setAttribute('data-show-tip','false'));
  });

  // Events module: create next-event + calendar list
  const events = [
    {id:1,title:'Morning Gather: Breath & Bowls',date:'2026-03-01T09:00:00',type:'group',location:'Studio A',price:20},
    {id:2,title:'Evening Wave: Resting Spectrum',date:'2026-03-05T18:30:00',type:'group',location:'Studio B',price:20},
    {id:3,title:'Seasonal Deep: Extended Practice',date:'2026-03-21T14:00:00',type:'intensive',location:'Main Hall',price:60}
  ];

  function isoToLocal(iso){const d=new Date(iso);return d.toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});} 
  // pick next event after now
  const now = new Date();
  const upcoming = events.filter(e=>new Date(e.date) > now).sort((a,b)=>new Date(a.date)-new Date(b.date));
  const nextEventNode = document.getElementById('nextEvent');
  const calendarListNode = document.getElementById('calendarList');
  if(nextEventNode){
    if(upcoming.length){
      const ne = upcoming[0];
      nextEventNode.innerHTML = `<h4>${ne.title}</h4><p class=\"muted\">${isoToLocal(ne.date)} — ${ne.location}</p><p><a class=\"btn primary\" href=\"events.html#${ne.id}\">RSVP</a></p>`;
    } else {
      nextEventNode.innerHTML = '<p class=\"muted\">No upcoming events — check back soon or sign up for announcements.</p>';
    }
  }
  if(calendarListNode){
    calendarListNode.innerHTML = upcoming.map((ev,idx)=>{
      const cls = idx===0? 'calendar-item next':'calendar-item';
      return `<div class=\"${cls}\"><strong>${ev.title}</strong><div class=\"muted\">${isoToLocal(ev.date)} — ${ev.location}</div></div>`;
    }).join('');
  }

  // Small UX: highlight recommended membership on intensity change
  const tierEls = document.querySelectorAll('.tier');
  function highlightTierByKey(key){
    tierEls.forEach(el=>el.style.outline='none');
    if(key==='gentle'){ document.querySelector('[data-tier="ripple"]').style.outline='3px solid rgba(61,179,158,0.14)'; }
    if(key==='medium'){ document.querySelector('[data-tier="current"]').style.outline='3px solid rgba(71,102,255,0.12)'; }
    if(key==='intense'){ document.querySelector('[data-tier="deep"]').style.outline='3px solid rgba(71,102,255,0.18)'; }
  }
  // initial
  highlightTierByKey(document.querySelector('input[name="intensity"]:checked').value);
  document.querySelectorAll('input[name="intensity"]').forEach(r=>r.addEventListener('change', e=>{ highlightTierByKey(e.target.value); }));

  // Accessibility: ensure badges are focusable
  badges.forEach(b=>{ b.setAttribute('tabindex','0'); });
});"} 
